String _orderLabel(ProductionMapSaved order, AppLocalizations l10n) {
  final map = order.map;
  final code = map.code.trim().isNotEmpty
      ? map.code.trim()
      : map.orderNumber.trim().isNotEmpty
          ? map.orderNumber.trim()
          : map.id.trim();
  final title = map.title.trim().isNotEmpty
      ? map.title.trim()
      : l10n.adminText('raw_material.order_fallback');
  return '$code · $title';
}

String _formatQty(double value, String uom) {
  return formatQuantityWithUnit(
    value,
    uom,
    decimalPlaces: 3,
    trimTrailingZeros: true,
  );
}

String _assignmentKey(AdminRawMaterialAssignment assignment) {
  return '${assignment.orderId.trim()}|${assignment.barcode.trim()}';
}

String _assignmentAssignee(AdminRawMaterialAssignment assignment) {
  final name = assignment.assignedByName.trim();
  if (name.isNotEmpty) {
    return name;
  }
  return assignment.assignedByRef.trim();
}

String _assignmentStockStatusLabel(String raw, AppLocalizations l10n) {
  return switch (raw.trim().toLowerCase()) {
    'available' => l10n.adminText('raw_material.status_available'),
    'in_use' => l10n.adminText('raw_material.status_in_use'),
    'reserved' => l10n.adminText('label.reserved'),
    'consumed' => l10n.adminText('raw_material.status_consumed'),
    '' => '',
    _ => raw.trim(),
  };
}

String _formatAssignmentTimestamp(String raw) {
  return formatParsedLocalDateTimeOrRaw(raw);
}
